package tasknet

import (
	"bytes"
	"fmt"
	"text/template"
)

const kernelTemplate = `
// Code generated by Go-Hybrid tasknet compiler. DO NOT EDIT.
package {{.Package}}

func {{.FunctionName}}(iterations int) {
	// Buffer definitions
	{{- range .Edges }}
	var buf_{{.ID}} [{{index $.Budgets .ID}}]float64
	rptr_{{.ID}}, wptr_{{.ID}} := 0, {{.InitialTokens}}
	{{- end }}

	for i := 0; i < iterations; i++ {
		{{- range .FiringOrder }}
		// Actor: {{.}}
		{
			{{- /* This is a simplified scalar kernel emitter */}}
			// Logic for {{.}} would be injected here
		}
		{{- end }}
	}
}
`

type GenContext struct {
	Package     string
	FunctionName string
	FiringOrder []string
	Edges       []*Edge
	Budgets     map[string]int
}

// EmitGo generates a sequential Go kernel for the verified network.
func EmitGo(pkg, name string, net *Network, sched *Schedule) (string, error) {
	if err := Verify(net, sched); err != nil {
		return "", fmt.Errorf("cannot emit: schedule failed verification: %w", err)
	}

	tmpl, err := template.New("kernel").Parse(kernelTemplate)
	if err != nil {
		return "", err
	}

	edgeList := make([]*Edge, 0, len(net.Edges))
	for _, e := range net.Edges {
		edgeList = append(edgeList, e)
	}

	ctx := GenContext{
		Package:      pkg,
		FunctionName: name,
		FiringOrder:  sched.FiringOrder,
		Edges:        edgeList,
		Budgets:      sched.Budgets,
	}

	var out bytes.Buffer
	if err := tmpl.Execute(&out, ctx); err != nil {
		return "", err
	}

	return out.String(), nil
}
